ev=json.loads((HERE/'evidence.json').read_text());clr=json.loads((HERE/'clr-evidence.json').read_text());v=json.loads((HERE/'verification.json').read_text())
selected=['0x060000A8','0x060000AA','0x060000BC','0x06000205','0x06000209','0x0600020A','0x0600020B','0x0600020C','0x0600020D','0x0600020E','0x0600020F','0x06000210','0x06000211','0x06000212','0x06000213','0x06000214','0x06000215','0x06000216','0x06000223','0x06000224','0x06000225']
lines=['Complete captured native listings; hexadecimal addresses are preferred-image VAs.','IDA names/comments are analysis annotations, not independent semantic proof.','Two discontiguous functions are explicitly separated from contiguous coverage bodies.','']
for f in sorted(ev['functions']+ev['chunkedFunctions'],key=lambda f:int(f['addr'],16)):
    lines += [f"FUNCTION {f['addr']} {f['name']}; instructions={f['instruction_count']}; IDA primary size={f['size']}"]
    if 'chunks' in f:
        lines += [f"CHUNK {c['addr']} bytes={c['size']} {c['originalBytes']}" for c in f['chunks']]
    else: lines += ['ORIGINAL '+f['originalBytes']]
    lines += [r['addr']+'  '+r['instruction'] for r in f['asm']['lines']]
    lines += ['', 'HEXRAYS (ASM is authoritative for arguments, tail calls and failure branches)',f['pseudocode']['code'],'']
(HERE/'native-listings.txt').write_text('\n'.join(lines)+'\n',encoding='utf-8')
lines=['Selected complete IL bodies. All 439 IL bodies and 597 MethodDefs are retained in clr-evidence.json.','Selection is for App/window/thread context; metadata inventory is not full semantic review.','']
for m in clr['methods']:
    if m['token'] not in selected:continue
    b=m['body'];lines += [f"METHOD {m['token']} {m['name']} RVA={m['rva']}",'ORIGINAL HEADER/BODY '+b['headerAndBodyBytes'],'EH '+json.dumps(b['exceptionRegions'])]
    for i in b['instructions']:lines.append(i['offset']+' '+i['bytes']+' '+i['op']+' '+json.dumps(i['operand'],ensure_ascii=False))
    lines.append('')
(HERE/'managed-listings.txt').write_text('\n'.join(lines)+'\n',encoding='utf-8')
